H.background();
const Pp = Math.max(0.1, P.P);
const Vv = Math.max(0.1, P.V);
const Tt = Math.max(1, P.T);
const mm = Math.max(0.01, P.mass);
const R = 0.08206;
const n = (Pp * Vv) / (R * Tt);
const M = mm / Math.max(1e-9, n);
const bx = 480, by = 110, bw = 360, bh = 360;
H.rect(bx, by, bw, bh, { stroke: H.colors.axis, width: 2 });
const Np = Math.max(4, Math.min(60, Math.round(n * 30)));
for (let i = 0; i < Np; i++) {
  const ph = i * 1.7;
  const sx = bx + 20 + ((i * 53) % (bw - 40));
  const sy = by + 20 + ((i * 97) % (bh - 40));
  const px = sx + (bw - 80) * 0.4 * Math.sin(t * (1 + (i % 5) * 0.2) + ph);
  const py = sy + (bh - 80) * 0.3 * Math.cos(t * (1.2 + (i % 4) * 0.25) + ph * 1.3);
  H.circle(Math.max(bx + 6, Math.min(bx + bw - 6, px)), Math.max(by + 6, Math.min(by + bh - 6, py)), 5, { fill: H.colors.accent2 });
}
H.text("ideal gas: n = PV/RT", bx + bw / 2, by - 14, { color: H.colors.sub, size: 12, align: "center" });
H.text("Molar mass of a gas: M = mRT / PV", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Weigh a gas sample, measure P, V, T -> find M", 24, 52, { color: H.colors.sub, size: 13 });
H.text("P = " + Pp.toFixed(2) + " atm", 24, 84, { color: H.colors.accent, size: 14 });
H.text("V = " + Vv.toFixed(2) + " L", 24, 108, { color: H.colors.accent, size: 14 });
H.text("T = " + Tt.toFixed(0) + " K", 24, 132, { color: H.colors.accent, size: 14 });
H.text("mass = " + mm.toFixed(2) + " g", 24, 156, { color: H.colors.accent, size: 14 });
H.text("n = PV/RT = " + n.toFixed(4) + " mol", 24, 196, { color: H.colors.good, size: 15 });
H.text("M = " + M.toFixed(1) + " g/mol", 24, 222, { color: H.colors.warn, size: 16, weight: 700 });
